//! Closed Cold Mountain society: private pre-hand search and paid exact-criminal continuation.
use crate::{catalog,engine::RuleResult,model::*,rules::*,society::{SocietyDefinition,SocietyDeckConstraint}};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="MSWM03";
pub(crate) const KEY:&str="mswm03-criminal-draw";
const OPEN:&str="mswm03-opening";
const DONE:&str="mswm03-opening-done";
const TITLE:&str="冷山帮：寻找并展示一张黑市入手，然后洗牌并抓5张";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Payment{pub discarded:Card,pub discarded_subtypes:Vec<String>,pub criminal:crate::msjc12::ExhaustedCharacter}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"弃牌并横置本方罪犯：抓1；若弃罪犯，令原支付角色潜伏",Timing::Standard,vec![Cost::Assets(2),Cost::ExhaustSource,Cost::MSWM03Payment],vec![],vec![Op::MSWM03Resolve],None);a.activation_only=true;with_abilities(vec![a])}
pub(crate) fn society()->SocietyDefinition{let mut card:catalog::CardDefinition=serde_json::from_value(serde_json::json!({"id":ID,"name":"冷山帮","kind":"society","type":"秘社/黑帮","subtypes":["黑帮"],"color":"黑","society":"冷山帮","unique":true,"supported":false,"text":"构筑时非黑且非中立牌不能超过12张。抓起始手牌前，从牌库寻找一张名为黑市的附属牌，展示后置于手中，然后洗牌。行动2、横置秘社、弃一张牌、横置一个本方罪犯角色：抓一张牌。若所弃的是罪犯牌，则令因发动该能力而横置的罪犯角色潜伏。"})).unwrap();card.abilities=definition().abilities.iter().map(|a|catalog::AbilitySummary{key:a.key.clone(),label:a.label.clone(),timing:"standard".into(),costs:a.costs.clone(),triggered:false}).collect();SocietyDefinition{card,subtitle:"菜鸟,滑头".into(),printed_cost:None,starting_hand:5,deck_constraints:vec![SocietyDeckConstraint::ColdMountainOffColorMaximum],unresolved_abilities:Default::default()}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("mswm03-")||a.costs.iter().any(|c|matches!(c,Cost::MSWM03Payment))||a.ops.iter().any(|o|matches!(o,Op::MSWM03Resolve))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("冷山帮必须保留原四项费用与抓牌潜伏程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("冷山帮完整定义不能移植或改写".into());}Ok(())}
impl Game{
 fn mswm03_live(&self,s:usize)->bool{self.players.get(s).is_some_and(|p|!p.eliminated&&p.society_zone.card.as_ref().is_some_and(|c|c.definition==ID&&c.owner==s&&c.controller==s&&!c.face_down))}
 pub(crate) fn mswm03_defer_hand(&mut self,s:usize)->bool{if !self.mswm03_live(s){return false;}self.players[s].society_zone.used_once_per_game.insert(OPEN.into());self.effects.push_back(Effect::MSWM03Opening{seat:s});true}
 fn mswm03_open_valid(&self,s:usize)->RuleResult<()>{if !self.mswm03_live(s)||self.turn!=1||!self.players[s].hand.is_empty()||!self.players[s].society_zone.used_once_per_game.contains(OPEN)||self.players[s].society_zone.used_once_per_game.contains(DONE){return Err("冷山帮缺原起手前授权".into());}Ok(())}
 fn mswm03_open_options(&self,s:usize)->Vec<ChoiceOption>{self.players[s].deck.iter().filter(|c|{let d=catalog::card(&c.definition);d.name=="黑市"&&catalog::has_kind(d,"attachment")}).map(|c|self.option(c,s,None,None)).collect()}
 pub(crate) fn mswm03_open(&mut self,s:usize)->RuleResult<()>{self.mswm03_open_valid(s)?;let options=self.mswm03_open_options(s);if options.is_empty(){return self.mswm03_open_finish(s,&[]);}self.choice(s,OPEN,TITLE.into(),options,1,1,None,ChoiceResolution::MSWM03Opening{seat:s});Ok(())}
 pub(crate) fn mswm03_open_finish(&mut self,s:usize,ids:&[String])->RuleResult<()>{self.mswm03_open_valid(s)?;let options=self.mswm03_open_options(s);if ids.len()!=usize::from(!options.is_empty())||ids.iter().any(|id|!options.iter().any(|o|o.id==*id)){return Err("须选本人牌库一张黑市附属；无合法牌才零张".into());}if let Some(id)=ids.first(){let i=self.players[s].deck.iter().position(|c|c.id==*id).unwrap();let c=self.players[s].deck.remove(i);self.note(format!("{} 展示检索的 {}",self.players[s].name,catalog::card(&c.definition).name));let c=self.fresh(c);self.players[s].hand.push(c);}let mut deck=std::mem::take(&mut self.players[s].deck);self.shuffle(&mut deck);self.players[s].deck=deck;self.players[s].society_zone.used_once_per_game.insert(DONE.into());self.draw(s,5)}
 fn mswm03_criminals(&self,actor:usize)->Vec<&Card>{self.in_play_cards().into_iter().filter(|(r,c)|r.is_some_and(|r|self.region_live(r))&&c.controller==actor&&!c.face_down&&!c.exhausted&&catalog::has_kind(catalog::card(&c.definition),"character")&&self.current_subtypes(c).iter().any(|s|s=="罪犯")).map(|(_,c)|c).collect()}
 pub(crate) fn mswm03_cost_candidates(&self,actor:usize)->Vec<Vec<String>>{self.players[actor].hand.iter().flat_map(|h|self.mswm03_criminals(actor).into_iter().map(move|c|vec![h.id.clone(),c.id.clone()])).collect()}
 pub(crate) fn mswm03_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&AbilitySpec,input:&Action)->RuleResult<PaidCost>{validate_ability(&s.card.definition,a)?;if *input!=(Action{card_id:Some(s.card.id.clone()),ability_id:Some(KEY.into()),cost_selected:input.cost_selected.clone(),..Action::new("activate")}){return Err("冷山帮行动只声明原弃牌及横置角色".into());}let ids=input.cost_selected.as_ref().filter(|v|v.len()==2&&v[0]!=v[1]).ok_or("依次选择一张手牌和一个本方未横置罪犯角色")?;let discarded=self.players[actor].hand.iter().find(|c|c.id==ids[0]&&!c.face_down).ok_or("须弃本方手牌")?.clone();let criminal=(*self.mswm03_criminals(actor).iter().find(|c|c.id==ids[1]).ok_or("须横置本方未横置明置罪犯角色")?).clone();let paid=Payment{discarded_subtypes:self.current_subtypes(&discarded),discarded,criminal:crate::msjc12::ExhaustedCharacter{subtypes:self.current_subtypes(&criminal),card:criminal}};self.discard_hand_card(actor,&ids[0])?;self.board_mut(&ids[1]).ok_or("原费用角色已离场")?.exhausted=true;Ok(PaidCost::MSWM03Payment(Box::new(paid)))}
 pub(crate) fn mswm03_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID&&!f.ability_key.starts_with("mswm03-")&&!f.steps.iter().any(|s|matches!(s.op,Op::MSWM03Resolve))&&!f.already_paid.iter().any(|p|matches!(p,PaidCost::MSWM03Payment(_))){return Ok(());}let s=&f.source;let c=&s.card;self.validate_resource_frame(f)?;
 if c.definition!=ID||f.actor>=self.players.len()||c.owner!=f.actor||c.controller!=f.actor||c.face_down||c.exhausted||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.ability_key!=KEY||!f.targets.is_empty()||f.chosen_region.is_some()||f.steps.len()!=1||!matches!(f.steps[0].op,Op::MSWM03Resolve)||f.steps[0].context!=f.actor||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted){return Err("冷山帮来源、阶段或程序损坏".into());}self.mobility_immutable_identity(c)?;
 let[PaidCost::Assets(ids),PaidCost::Exhausted(source),PaidCost::MSWM03Payment(p)]=f.already_paid.as_slice()else{return Err("冷山帮缺完整原四项支付".into());};let v=&p.criminal.card;let d=&p.discarded;
 if f.money_units(0)!=2||source!=&c.id||ids.iter().any(|id|!self.mystic_instance_valid(id))||ids.iter().collect::<BTreeSet<_>>().len()!=ids.len()||v.id==d.id||v.id==c.id||d.id==c.id||ids.contains(&v.id)||ids.contains(&d.id)||v.controller!=f.actor||d.controller!=f.actor||v.owner>=self.players.len()||d.owner>=self.players.len()||v.face_down||v.exhausted||d.face_down||!catalog::has_kind(catalog::card(&v.definition),"character")||!p.criminal.subtypes.iter().any(|s|s=="罪犯")||p.criminal.subtypes.iter().collect::<BTreeSet<_>>().len()!=p.criminal.subtypes.len()||p.discarded_subtypes.iter().collect::<BTreeSet<_>>().len()!=p.discarded_subtypes.len()||p.discarded_subtypes.iter().any(|s|s=="罪犯")!=catalog::card(&d.definition).subtypes.iter().any(|s|s=="罪犯")||!self.mystic_instance_valid(&v.id)||!self.mystic_instance_valid(&d.id){return Err("冷山帮原弃牌或罪犯横置收据不符".into());}self.mobility_immutable_identity(v)?;self.mobility_immutable_identity(d)?;Ok(())}
 pub(crate) fn mswm03_resolve(&mut self,f:ResolutionFrame)->RuleResult<()>{self.mswm03_frame(&f)?;if f.ability_key!=KEY||f.cursor!=1{return Err("冷山帮须消费原第一步".into());}let PaidCost::MSWM03Payment(p)=&f.already_paid[2]else{unreachable!()};self.draw(f.actor,1)?;if p.discarded_subtypes.iter().any(|s|s=="罪犯")&&self.board(&p.criminal.card.id).is_some_and(|(_,c)|!c.face_down&&catalog::has_kind(catalog::card(&c.definition),"character")){self.hide_in_place(&p.criminal.card.id);}Ok(())}
 pub(crate) fn validate_mswm03_state(&self)->RuleResult<()>{let mut openings=BTreeSet::new();let mut frames=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.mswm03_frame(f)?;if f.source.card.definition==ID&&!frames.insert(f.frame_id.clone()){return Err("同一冷山帮行动不能重复续体".into());}Ok(())};
 for e in &self.effects{match e{Effect::MSWM03Opening{seat}=>{self.mswm03_open_valid(*seat)?;if !openings.insert(*seat){return Err("重复冷山帮起手续体".into());}},Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("冷山帮没有此运行时声明".into()),_=>{}}}
 for i in &self.stack{if let Some(f)=&i.frame{check(f)?;if f.source.card.definition==ID&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.is_some()||f.cursor!=0){return Err("冷山帮堆叠外壳损坏".into());}}}
 if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::MSWM03Opening{seat}=>{self.mswm03_open_valid(*seat)?;let expected=Choice{id:p.choice.id.clone(),kind:OPEN.into(),title:TITLE.into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(*seat),options:self.mswm03_open_options(*seat),preview_cards:vec![],min:Some(1),max:Some(1),amount:None,allow_decline:Some(false)};if !openings.insert(*seat)||p.seat!=*seat||!self.mystic_instance_valid(&p.choice.id)||expected.options.is_empty()||!same(&p.choice,&expected){return Err("冷山帮起手选择损坏".into());}},ChoiceResolution::Frame{frame,..}=>{check(frame)?;if frame.source.card.definition==ID{return Err("冷山帮付费行动不产生待选".into());}},ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>return Err("冷山帮不能恢复此声明".into()),_=>{}}}
 for p in &self.players{let marks=&p.society_zone.used_once_per_game;if marks.contains(DONE)&&!marks.contains(OPEN)||marks.contains(OPEN)&&!marks.contains(DONE)&&!openings.contains(&p.seat)||self.turn>0&&p.deck_snapshot.as_ref().is_some_and(|d|d.society_id.as_deref()==Some(ID))&&!marks.contains(OPEN){return Err("冷山帮起手授权或续体丢失".into());}}Ok(())}
}
